        const chatWindow = document.getElementById('chat-window');
        const userInput = document.getElementById('user-input');
        const sendBtn = document.getElementById('send-btn');

        // Teljes üzenettörténet – a kontextus megőrzéséhez
        let conversationHistory = [
            {
                role: "system",
                content: "Te egy hasznos AI asszisztens vagy. Magyarul válaszolj, ha a felhasználó magyarul ír."
            }
        ];

        function addMessage(role, content, isStreaming = false) {
            const div = document.createElement('div');
            div.className = `message ${role}${isStreaming ? ' streaming' : ''}`;
            div.textContent = content;
            chatWindow.appendChild(div);
            chatWindow.scrollTop = chatWindow.scrollHeight;
            return div;
        }

        async function sendMessage() {
            const text = userInput.value.trim();
            if (!text || sendBtn.disabled) return;

            // Felhasználó üzenetének megjelenítése
            addMessage('user', text);
            conversationHistory.push({ role: "user", content: text });
            userInput.value = '';
            userInput.style.height = 'auto';

            // UI tiltása küldés közben
            sendBtn.disabled = true;
            sendBtn.textContent = '...';

            // Streaming asszisztens válasz placeholder
            const assistantDiv = addMessage('assistant', '', true);
            let fullResponse = '';

            try {
                const response = await fetch('/chat', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ messages: conversationHistory })
                });

                const reader = response.body.getReader();
                const decoder = new TextDecoder();

                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;

                    const chunk = decoder.decode(value, { stream: true });
                    const lines = chunk.split('\n');

                    for (const line of lines) {
                        if (line.startsWith('data: ')) {
                            const data = line.slice(6).trim();
                            if (data === '[DONE]') {
                                assistantDiv.classList.remove('streaming');
                                break;
                            }
                            try {
                                const parsed = JSON.parse(data);
                                if (parsed.content) {
                                    fullResponse += parsed.content;
                                    assistantDiv.textContent = fullResponse;
                                    chatWindow.scrollTop = chatWindow.scrollHeight;
                                }
                            } catch (e) { /* chunk parse hiba, skip */ }
                        }
                    }
                }

                // Teljes választ hozzáadjuk a történethez
                conversationHistory.push({ role: "assistant", content: fullResponse });

            } catch (error) {
                assistantDiv.classList.remove('streaming');
                assistantDiv.textContent = '❌ Hiba történt: ' + error.message;
                assistantDiv.style.color = '#ff6b6b';
            }

            sendBtn.disabled = false;
            sendBtn.textContent = 'Küldés ▶';
        }

        // Enter = küldés, Shift+Enter = új sor
        userInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        // Auto-resize textarea
        userInput.addEventListener('input', () => {
            userInput.style.height = 'auto';
            userInput.style.height = Math.min(userInput.scrollHeight, 200) + 'px';
        });

        sendBtn.addEventListener('click', sendMessage);
    </script>
