                <button id="stop-btn" title="Generálás leállítása">⏹</button>
                <button id="send-btn" title="Küldés (Enter)">▶</button>
            </div>
        </div>
        <div class="input-hint">Enter = küldés &nbsp;·&nbsp; Shift+Enter = új sor</div>
    </div>
